65	std::optional<SmallVector<emitasc::KernelArgument>> getKernelArgAttrs(ModuleOp op)
66	{
67	    func::FuncOp kernelFunc;
68	    op.walk([&](func::FuncOp fn) -> WalkResult {
69	        if (fn->hasAttrOfType<UnitAttr>(ascendc::attr::global)) {
70	            kernelFunc = fn;
71	            return WalkResult::interrupt();
72	        }
73	        return WalkResult::advance();
74	    });
75	    if (!kernelFunc) {
76	        return std::nullopt;
77	    }
78	    SmallVector<emitasc::KernelArgument> kernelArgs;
79	    unsigned numArgs = kernelFunc.getNumArguments();
80	    kernelArgs.reserve(numArgs);
81	    for (unsigned i = 0; i < numArgs; i++) {
82	        auto attr = kernelFunc.getArgAttrOfType<emitasc::KernelArgumentAttr>(i, emitasc::attr::kernelArg);
83	        kernelArgs.push_back(attr ? attr.getValue() : emitasc::KernelArgument::Explicit);
84	    }
85	    return kernelArgs;
86	}
