186	void bindContextAndDialect(py::module& m)
187	{
188	    py::class_<MLIRContext>(m, "Context", py::module_local())
189	        .def(py::init<>())
190	        .def("disable_multithreading", [](MLIRContext& self) { self.disableMultithreading(); });
191	
192	    m.def("load_dialects", [](MLIRContext& context) {
193	        DialectRegistry registry;
194	        registry.insert<
195	            //
196	            arith::ArithDialect, ascendc::AscendCDialect, emitasc::EmitAscDialect, emitc::EmitCDialect,
197	            func::FuncDialect, memref::MemRefDialect, scf::SCFDialect, vector::VectorDialect
198	            //
199	            >();
200	        ascendc::registerExternalModels(registry);
201	        ascendc::registerInlinerInterfaces(registry);
202	        emitasc::registerExternalModels(registry);
203	        func::registerAllExtensions(registry);
204	        context.appendDialectRegistry(registry);
205	        context.loadAllAvailableDialects();
206	    });
207	}
