209	void bindType(py::module& m)
210	{
211	    py::class_<Type>(m, "Type", py::module_local())
212	        .def("is_integer", [](Type& self) -> bool { return self.isInteger(); })
213	        .def("is_index", &Type::isIndex)
214	        .def(
215	            "__eq__",
216	            [](Type& self, py::object& other) {
217	                Type* otherTy = py::cast<Type*>(other);
218	                return (otherTy != nullptr) && (*otherTy == self);
219	            })
220	        .def(
221	            "__ne__",
222	            [](Type& self, py::object& other) {
223	                Type* otherTy = py::cast<Type*>(other);
224	                return (otherTy == nullptr) || (*otherTy != self);
225	            })
226	        .def(
227	            "get_py_name",
228	            [](Type& self) -> std::optional<std::string> {
229	                if (isa<IntegerType>(self)) {
230	                    std::string name = self.isUnsignedInteger() ? "uint" : "int";
231	                    name += std::to_string(self.getIntOrFloatBitWidth());
232	                    return name;
233	                }
234	                if (isa<FloatType>(self)) {
235	                    std::string name = "float";
236	                    name += std::to_string(self.getIntOrFloatBitWidth());
237	                    return name;
238	                }
239	                if (isa<NoneType>(self))
240	                    return "void";
241	                return std::nullopt;
242	            })
243	        .def("__str__", [](Type& self) {
244	            std::string str;
245	            llvm::raw_string_ostream os(str);
246	            self.print(os);
247	            os.flush();
248	            return os.str();
249	        });
250	}
