252	void bindMemref(py::module& m)
253	{
254	    using namespace pybind11::literals;
255	    m.def("get_element_type", [](const Type& shapedType) -> Type {
256	        auto type = llvm::dyn_cast_if_present<ShapedType>(shapedType);
257	        if (!type)
258	            throw std::runtime_error("get_element_type(): must be shaped type");
259	        return type.getElementType();
260	    });
261	
262	    m.def("get_shape", [](const Type& shapedType) -> std::vector<int64_t> {
263	        auto type = llvm::dyn_cast_if_present<ShapedType>(shapedType);
264	        if (!type)
265	            throw std::runtime_error("get_shape(): must be shaped type");
266	        return type.getShape().vec();
267	    });
268	
269	    m.def("get_vector_type", [](Type& elementType, std::vector<int64_t>& shape) -> Type {
270	        return VectorType::get(shape, elementType);
271	    });
272	
273	    m.def(
274	        "get_memref_type",
275	        [](Type& elementType, const std::variant<std::vector<int64_t>, int64_t>& shape,
276	           std::optional<int64_t> addressSpace) -> Type {
277	            Attribute memorySpace;
278	            if (auto as = addressSpace.value_or(0)) {
279	                memorySpace = IntegerAttr::get(IntegerType::get(elementType.getContext(), index64), as);
280	            }
281	            SmallVector<int64_t> sh;
282	            if (std::holds_alternative<int64_t>(shape)) {
283	                sh.push_back(std::get<int64_t>(shape));
284	            } else {
285	                const auto& shapeVec = std::get<std::vector<int64_t>>(shape);
286	                sh.append(shapeVec.begin(), shapeVec.end());
287	            }
288	            return MemRefType::get(sh, elementType, AffineMap{}, memorySpace);
289	        },
290	        "element_type"_a, "shape"_a, "address_space"_a = py::none());
291	    m.def(
292	        "get_unranked_memref_type",
293	        [](Type& elementType, std::optional<int64_t> addressSpace) -> Type {
294	            Attribute memorySpace;
295	            if (auto as = addressSpace.value_or(0))
296	                memorySpace = IntegerAttr::get(IntegerType::get(elementType.getContext(), index64), as);
297	            return UnrankedMemRefType::get(elementType, memorySpace);
298	        },
299	        "element_type"_a, "address_space"_a = py::none());
300	}
