335	void bindValue(py::module& m)
336	{
337	    using ret = py::return_value_policy;
338	    py::class_<Value>(m, "Value", py::module_local())
339	        .def("get_context", &Value::getContext, ret::reference)
340	        .def(
341	            "get_defining_op",
342	            [](Value& self) -> std::optional<Operation*> {
343	                auto* def = self.getDefiningOp();
344	                if (def)
345	                    return def;
346	                return std::nullopt;
347	            },
348	            ret::reference)
349	        .def("replace_all_uses_with", [](Value& self, Value& newValue) { self.replaceAllUsesWith(newValue); })
350	        .def(
351	            "replace_uses_in_block",
352	            [](Value& self, Block* block, Value& newValue) {
353	                self.replaceUsesWithIf(newValue, [block](OpOperand& opnd) -> bool {
354	                    auto* op = opnd.getOwner();
355	                    Block* parentBlock = op->getBlock();
356	                    while (parentBlock) {
357	                        if (parentBlock == block)
358	                            return true;
359	                        if (auto* parentOp = parentBlock->getParentOp())
360	                            parentBlock = parentOp->getBlock();
361	                        else
362	                            parentBlock = nullptr;
363	                    }
364	                    return false;
365	                });
366	            })
367	        .def("get_type", &Value::getType)
368	        .def("dump", &Value::dump)
369	        .def("id", [](Value& self) { return reinterpret_cast<uint64_t>(self.getImpl()); });
370	}
