372	void bindRegion(py::module& m)
373	{
374	    using ret = py::return_value_policy;
375	    py::class_<OpResult, Value>(m, "OpResult", py::module_local());
376	    py::class_<BlockArgument, Value>(m, "BlockArgument", py::module_local());
377	    py::class_<Region>(m, "Region", py::module_local())
378	        .def("get_parent_region", &Region::getParentRegion, ret::reference)
379	        .def(
380	            "get_block",
381	            [](Region& self, unsigned index) -> Block& {
382	                if (index >= self.getBlocks().size())
383	                    throw std::runtime_error("block index is out of range");
384	                return *std::next(self.begin(), index);
385	            },
386	            ret::reference)
387	        .def("size", [](Region& self) { return self.getBlocks().size(); })
388	        .def("empty", &Region::empty)
389	        .def("id", [](Region& self) { return (uint64_t)&self; });
390	}
