392	void bindBlocks(py::module& m)
393	{
394	    using ret = py::return_value_policy;
395	    py::class_<Block>(m, "Block", py::module_local())
396	        .def(py::init())
397	        .def("dump", &Block::dump)
398	        .def("id", [](Block& self) { return (uint64_t)&self; })
399	        .def("has_terminator", &Block::mightHaveTerminator)
400	        .def("get_terminator", &Block::getTerminator, ret::reference)
401	        .def(
402	            "add_argument",
403	            [](Block& self, Type& type) -> BlockArgument {
404	                return self.addArgument(type, UnknownLoc::get(type.getContext()));
405	            })
406	        .def("get_argument", &Block::getArgument)
407	        .def("get_arguments", [](Block& self) -> std::vector<BlockArgument> { return self.getArguments().vec(); })
408	        .def(
409	            "merge_block_before",
410	            [](Block& self, Block& dst) {
411	                // See RewriterBase::mergeBlocks()
412	                if (self.getNumArguments() != 0)
413	                    throw std::runtime_error("Unable to merge block with arguments");
414	                dst.getOperations().splice(dst.begin(), self.getOperations());
415	                self.dropAllUses();
416	                if (self.getParent())
417	                    self.erase();
418	            })
419	        .def("clear", &Block::clear)
420	        .def("erase", &Block::erase);
421	}
