423	void bindInlineBlock(py::module& m)
424	{
425	    using namespace pybind11::literals;
426	
427	    m.def(
428	        "inline_block_at_end",
429	        [](Block* src, Block* dst, const std::optional<std::vector<Value>>& args) {
430	            // See RewriterBase::inlineBlockBefore()
431	            ValueRange argValues({});
432	            if (args)
433	                argValues = *args;
434	            auto before = dst->end();
435	            if (argValues.size() != src->getNumArguments())
436	                throw std::runtime_error("incorrect # of argument replacement values");
437	            // Replace all of the successor arguments with the provided values
438	            for (auto [arg, newVal] : llvm::zip(src->getArguments(), argValues))
439	                arg.replaceAllUsesWith(newVal);
440	            dst->getOperations().splice(before, src->getOperations());
441	            if (!src->empty()) {
442	                throw std::runtime_error("expected 'src' to be empty");
443	            }
444	            if (src->getParent())
445	                src->erase();
446	        },
447	        "src"_a, "dst"_a, "args"_a = py::none());
448	}
