477	        .def("get_region", &Operation::getRegion, ret::reference)
478	        .def("get_block", &Operation::getBlock, ret::reference)
479	        .def(
480	            "has_unit_attr",
481	            [](Operation& self, const std::string& name) -> bool { return self.hasAttrOfType<UnitAttr>(name); })
482	        .def(
483	            "get_str_attr",
484	            [](Operation& self, const std::string& name) -> std::optional<std::string> {
485	                auto ret = self.getAttrOfType<StringAttr>(name);
486	                if (!ret)
487	                    return std::nullopt;
488	                return ret.getValue().str();
489	            })
490	        .def(
491	            "get_bool_attr",
492	            [](Operation& self, const std::string& name) -> std::optional<bool> {
493	                auto ret = self.getAttrOfType<BoolAttr>(name);
494	                if (!ret)
495	                    return std::nullopt;
496	                return ret.getValue();
497	            })
498	        .def(
499	            "get_integer_attr",
500	            [](Operation& self, const std::string& name) -> py::object {
501	                auto ret = self.getAttrOfType<IntegerAttr>(name);
502	                if (!ret)
503	                    return py::none();
504	                return py::int_(ret.getValue().getSExtValue());
505	            })
506	        .def("get_flat_symbol_ref_attr", [](Operation& self, const std::string& name) -> py::object {
507	            auto ret = self.getAttrOfType<FlatSymbolRefAttr>(name);
508	            if (!ret)
509	                return py::none();
510	            return py::str(ret.getValue().str());
511	        });
512	}
513	
514	void bindOpstate(py::module& m)
515	{
516	    using ret = py::return_value_policy;
517	    py::class_<OpState>(m, "OpState", py::module_local())
518	        .def("get_context", &OpState::getContext, ret::reference)
519	        .def("set_attr", [](OpState& self, std::string& name, Attribute& attr) { self->setAttr(name, attr); })
520	        .def("get_num_results", [](OpState& self) -> unsigned { return self->getNumResults(); })
521	        .def(
522	            "get_result",
523	            [](OpState& self, unsigned idx) -> Value {
524	                if (idx >= self->getNumResults())
525	                    throw pybind11::index_error("Op result index out of range");
526	                return self->getResult(idx);
527	            })
528	        .def(
529	            "get_region",
530	            [](OpState& self, unsigned idx) -> Region& {
531	                if (idx >= self->getNumRegions())
532	                    throw pybind11::index_error("Op region index out of range");
533	                return self->getRegion(idx);
534	            },
535	            ret::reference)
536	        .def("dump", [](OpState& self) { self->dump(); })
537	        .def(
538	            "__str__",
539	            [](OpState& self) -> std::string {
540	                std::string str;
541	                llvm::raw_string_ostream os(str);
542	                auto printingFlags = getOpPrintingFlags();
543	                self->print(os, printingFlags);
544	                return str;
545	            })
546	        .def("append_operand", [](OpState& self, Value& val) { self->insertOperands(self->getNumOperands(), val); })
547	        .def("verify", [](OpState& self) -> bool { return succeeded(verify(self.getOperation())); })
548	        .def_property_readonly("op", &OpState::getOperation, ret::reference);
549	}
550	
551	void bindModuleop(py::module& m)
552	{
553	    using ret = py::return_value_policy;
554	    using namespace pybind11::literals;
555	
556	    py::class_<ModuleOp, OpState>(m, "ModuleOp", py::module_local())
557	        .def("dump", &ModuleOp::dump)
558	        .def(
559	            "get_body", [](ModuleOp& self) -> Block* { return self.getBody(); }, ret::reference)
560	        .def(
561	            "has_function",
562	            [](ModuleOp& self, const std::string& name, const std::optional<Type>& type) -> bool {
563	                auto* op = SymbolTable::lookupSymbolIn(self, name);
564	                if (auto funcOp = dyn_cast_if_present<func::FuncOp>(op))
565	                    return !type || funcOp.getFunctionType() == *type;
566	                return false;
567	            },
568	            "name"_a, "type"_a = py::none())
569	        .def(
570	            "need_insert_sync",
571	            [](ModuleOp& self) {
572	                auto result = self.walk([](ascendc::LocalTensorAutoOp) { return WalkResult::interrupt(); });
573	                return result.wasInterrupted();
574	            })
575	        .def("erase", [](ModuleOp& self) { self->erase(); });
576	}
577	
578	void bindFuncop(py::module& m)
579	{
580	    using ret = py::return_value_policy;
581	    py::class_<func::FuncOp, OpState>(m, "FuncOp", py::module_local())
582	        .def(
583	            "get_arg",
584	            [](func::FuncOp& self, unsigned idx) -> BlockArgument {
585	                if (idx >= self.getNumArguments())
586	                    throw pybind11::index_error("Function argument index out of range");
587	                return self.getArgument(idx);
588	            })
589	        .def("get_num_args", &func::FuncOp::getNumArguments)
590	        .def(
591	            "add_entry_block", [](func::FuncOp& self) -> Block* { return self.addEntryBlock(); }, ret::reference)
592	        .def(
593	            "set_type",
594	            [](func::FuncOp& self, const Type& funcType) {
595	                auto type = dyn_cast<FunctionType>(funcType);
596	                if (!type)
597	                    throw std::runtime_error("set_type(): must be FunctionType");
598	                self.setFunctionType(type);
599	            })
600	        .def(
601	            "set_arg_names",
602	            [](func::FuncOp& self, const std::vector<std::string>& names) {
603	                if (names.size() != self.getNumArguments())
604	                    throw std::runtime_error("Number of names must be equal to number of arguments");
605	                for (unsigned i = 0; i < names.size(); i++) {
606	                    auto arg = self.getArgument(i);
607	                    auto name = StringAttr::get(self.getContext(), names[i]);
608	                    arg.setLoc(NameLoc::get(name, arg.getLoc()));
609	                }
610	            })
611	        .def(
612	            "get_body", [](func::FuncOp& self) -> Block& { return self.getFunctionBody().front(); }, ret::reference)
613	        .def(
614	            "make_aicore",
615	            [](func::FuncOp& self) { self->setAttr(ascendc::attr::aicore, UnitAttr::get(self.getContext())); })
616	        .def("make_global", [](func::FuncOp& self) {
617	            self.setPublic();
618	            self->setAttr(ascendc::attr::global, UnitAttr::get(self.getContext()));
619	        });
620	}
621	
622	void bindScfop(py::module& m)
623	{
624	    using ret = py::return_value_policy;
625	    py::class_<scf::ForOp, OpState>(m, "ForOp", py::module_local())
626	        .def("get_induction_var", &scf::ForOp::getInductionVar)
627	        .def("get_body", [](scf::ForOp& self) -> Block* { return self.getBody(); }, ret::reference);
628	    py::class_<scf::IfOp, OpState>(m, "IfOp", py::module_local())
629	        .def("get_then_block", &scf::IfOp::thenBlock, ret::reference)
630	        .def("get_else_block", &scf::IfOp::elseBlock, ret::reference)
631	        .def("get_then_yield", &scf::IfOp::thenYield)
632	        .def("get_else_yield", &scf::IfOp::elseYield);
633	    py::class_<scf::YieldOp, OpState>(m, "YieldOp", py::module_local());
634	    py::class_<scf::WhileOp, OpState>(m, "WhileOp", py::module_local())
635	        .def("get_before", &scf::WhileOp::getBefore, ret::reference)
636	        .def("get_after", &scf::WhileOp::getAfter, ret::reference);
637	    py::class_<scf::ConditionOp, OpState>(m, "ConditionOp", py::module_local());
638	}
639	
640	void bindKernelArgument(py::module& m)
641	{
642	    py::enum_<emitasc::KernelArgument>(m, "KernelArgument", py::module_local())
643	        .value("Explicit", emitasc::KernelArgument::Explicit)
644	        .value("FftsAddr", emitasc::KernelArgument::FftsAddr);
645	
646	    m.def("get_kernel_arg_attrs", [](ModuleOp& mod) -> py::object {
647	        auto kernelArgs = getKernelArgAttrs(mod);
648	        if (!kernelArgs) {
649	            return py::none();
650	        }
651	        py::list result;
652	        for (auto arg : kernelArgs.value()) {
653	            result.append(arg);
654	        }
655	        return result;
656	    });
657	}
658	
659	} // namespace
660	
661	namespace pybind11 {
662	namespace asc {
663	void initIRModule(py::module&& m)
664	{
665	    bindEnums(m);
666	    bindContextAndDialect(m);
667	    bindType(m);
668	    bindMemref(m);
669	    bindTensorType(m);
670	    bindLocation(m);
671	    bindValue(m);
672	    bindRegion(m);
673	    bindBlocks(m);
674	    bindInlineBlock(m);
675	    bindAttritube(m);
676	    bindOperation(m);
677	    bindOpstate(m);
678	    bindModuleop(m);
679	    bindFuncop(m);
680	    bindScfop(m);
681	    bindKernelArgument(m);
682	    py::class_<OpBuilder::InsertPoint>(m, "InsertPoint", py::module_local());
683	
684	    initBuilderInIRModule(m);
685	}
686	} // namespace asc
687	} // namespace pybind11
