54	class PyOpBuilder {
55	    OpBuilder builder;
56	    Location loc;
57	
58	public:
59	    explicit PyOpBuilder(MLIRContext* context) : builder(context), loc(builder.getUnknownLoc()) {}
60	    ~PyOpBuilder() = default;
61	
62	    void setLoc(Location newLoc) { loc = newLoc; }
63	
64	    void setLoc(const std::string& name, bool reset = false)
65	    {
66	        if (reset) {
67	            setLoc(NameLoc::get(builder.getStringAttr(name)));
68	        } else {
69	            setLoc(NameLoc::get(builder.getStringAttr(name), loc));
70	        }
71	    }
72	
73	    void setLoc(const std::string& fileName, int line, int column, const std::optional<std::string>& name)
74	    {
75	        Location newLoc = FileLineColLoc::get(builder.getContext(), fileName, line, column);
76	        if (name) {
77	            newLoc = NameLoc::get(builder.getStringAttr(*name), newLoc);
78	        }
79	        setLoc(newLoc);
80	    }
81	
82	    Location getLoc() { return loc; }
83	
84	    void resetLoc() { loc = builder.getUnknownLoc(); }
85	
86	    OpBuilder& getBuilder() { return builder; }
87	
88	    OpBuilder* operator->() { return &builder; }
89	
90	    void setInsertionPointToStart(Block& block)
91	    {
92	        if (!block.empty()) {
93	            setLoc(block.begin()->getLoc());
94	        } else {
95	            resetLoc();
96	        }
97	        builder.setInsertionPointToStart(&block);
98	    }
99	
100	    void setInsertionPointToEnd(Block& block)
101	    {
102	        if (!block.empty()) {
103	            setLoc(block.back().getLoc());
104	        } else {
105	            resetLoc();
106	        }
107	        builder.setInsertionPointToEnd(&block);
108	    }
109	
110	    void setInsertionPointAfter(Operation& op)
111	    {
112	        setLoc(op.getLoc());
113	        builder.setInsertionPointAfter(&op);
114	    }
115	
116	    void restoreInsertionPoint(OpBuilder::InsertPoint pt)
117	    {
118	        if (pt.isSet() && pt.getPoint() != pt.getBlock()->end()) {
119	            setLoc(pt.getPoint()->getLoc());
120	        } else if (pt.isSet() && !pt.getBlock()->empty()) {
121	            setLoc(pt.getBlock()->back().getLoc());
122	        } else {
123	            resetLoc();
124	        }
125	        builder.restoreInsertionPoint(pt);
126	    }
127	
128	    Operation* create(
129	        StringRef operationName, ValueRange operands, TypeRange types = {}, ArrayRef<NamedAttribute> attributes = {})
130	    {
131	        return builder.create(loc, builder.getStringAttr(operationName), operands, types, attributes);
132	    }
133	
134	    template <typename OpTy, typename... Args>
135	    auto create(Args&&... args) -> OpTy
136	    {
137	        return builder.create<OpTy>(loc, std::forward<Args>(args)...);
138	    }
139	
140	    // Overload to create or fold a single result operation.
141	    template <typename OpTy, typename... Args>
142	    std::enable_if_t<OpTy::template hasTrait<OpTrait::OneResult>(), Value> createOrFold(Args&&... args)
143	    {
144	        return builder.createOrFold<OpTy>(loc, std::forward<Args>(args)...);
145	    }
146	
147	    // Overload to create or fold a zero result operation.
148	    template <typename OpTy, typename... Args>
149	    std::enable_if_t<OpTy::template hasTrait<OpTrait::ZeroResults>(), OpTy> createOrFold(Args&&... args)
150	    {
151	        return builder.createOrFold<OpTy>(loc, std::forward<Args>(args)...);
152	    }
153	
154	    std::optional<func::FuncOp> getCurrentFunction()
155	    {
156	        Block* block = builder.getInsertionBlock();
157	        if (!block) {
158	            return std::nullopt;
159	        }
160	        Operation* parent = block->getParentOp();
161	        if (!parent) {
162	            return std::nullopt;
163	        }
164	        if (auto op = dyn_cast<func::FuncOp>(parent)) {
165	            return op;
166	        }
167	        if (auto op = parent->getParentOfType<func::FuncOp>()) {
168	            return op;
169	        }
170	        return std::nullopt;
171	    }
172	};
