964	                throw std::runtime_error("Unknown mode for GatherMaskOp");
965	            }
966	            return self.create<ascendc::GatherMaskOp>(type, dst, src0, src1Pattern, reduceMode, mask, params, *modeAttr)
967	                .getResult();
968	        });
969	    clss.def(
970	        "create_asc_GetMrgSortResults",
971	        [](PyOpBuilder& self, const Type& type1, const Type& type2, const Type& type3, const Type& type4) {
972	            auto operation = self.create<ascendc::GetMrgSortResultOp>(type1, type2, type3, type4);
973	            return py::make_tuple(
974	                operation.getResult(0), operation.getResult(1), operation.getResult(2), operation.getResult(3));
975	        });
976	    clss.def(
977	        "create_asc_GetStoreAtomicConfigAndResult",
978	        [](PyOpBuilder& self, const Type& type, const Type& op) {
979	            auto operation = self.create<ascendc::GetStoreAtomicConfigOp>(type, op);
980	            return py::make_tuple(operation.getResult(0), operation.getResult(1));
981	        },
982	        "type"_a, "op"_a);
983	    clss.def("create_asc_SetStoreAtomicConfigOp", [](PyOpBuilder& self, uint8_t type, uint8_t op) {
984	        auto typeAttr = ascendc::symbolizeAtomicDtype(type);
985	        if (!typeAttr) {
986	            throw std::runtime_error("Unknown type for AtomicDtype");
987	        }
988	        auto opAttr = ascendc::symbolizeAtomicOp(op);
989	        if (!opAttr) {
990	            throw std::runtime_error("Unknown type for AtomicOp");
991	        }
992	        self.create<ascendc::SetStoreAtomicConfigOp>(*typeAttr, *opAttr);
993	    });
994	    clss.def(
995	        "create_asc_GetStoreAtomicConfigAndResult",
996	        [](PyOpBuilder& self, const Type& type, const Type& op) {
997	            auto operation = self.create<ascendc::GetStoreAtomicConfigOp>(type, op);
998	            return py::make_tuple(operation.getResult(0), operation.getResult(1));
999	        },
1000	        "type"_a, "op"_a);
1001	}
